   ): number;
 }

 export class FreeShippingCalculator implements ShippingCalculator {
   computeShippingCents(
     _lines: readonly CartLine[],
     _subtotalCents: number,
   ): number {
     return 0;
   }
 }

 /**
  * Flat shipping fee with optional free-over-threshold logic.
  */
