describe("WeightBasedShippingCalculator", () => {
  it("rejects empty brackets", () => {
    expect(() => new WeightBasedShippingCalculator([])).toThrow(
      "at least one weight bracket is required",
    );
  });

  it("rejects bracket with non-positive upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("rejects bracket with negative costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
    ).toThrow(RangeError);
  });

  it("rejects non-integer upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 10.5, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("rejects non-integer costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: 5.5 }]),
    ).toThrow(RangeError);
  });

  it("rejects negative overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 100, costCents: 100 }],
          -1,
        ),
    ).toThrow(RangeError);
  });

  it("rejects non-integer overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 100, costCents: 100 }],
          5.5,
        ),
    ).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
    ]);
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });

  it("returns 0 for zero-weight items", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 100, 1)], 100)).toBe(0);
  });

  it("selects the correct bracket", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 2000, costCents: 800 },
    ]);
    // 200g item → first bracket
    expect(calc.computeShippingCents([makeLine("a", 100, 1, 200)], 100)).toBe(300);
    // 700g item → second bracket
    expect(calc.computeShippingCents([makeLine("a", 100, 1, 700)], 100)).toBe(500);
    // 1500g item → third bracket
    expect(calc.computeShippingCents([makeLine("a", 100, 1, 1500)], 100)).toBe(800);
  });

  it("boundary: weight exactly at bracket limit selects that bracket", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 100, 1, 500)], 100)).toBe(300);
    expect(calc.computeShippingCents([makeLine("a", 100, 1, 1000)], 100)).toBe(500);
  });

  it("boundary: weight just over bracket goes to next", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 100, 1, 501)], 100)).toBe(500);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
      ],
      1200,
    );
    expect(calc.computeShippingCents([makeLine("a", 100, 1, 1500)], 100)).toBe(1200);
  });

  it("defaults overflow to heaviest bracket cost", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 100, 1, 5000)], 100)).toBe(500);
  });

  it("sorts brackets internally regardless of input order", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 500, costCents: 300 },
    ]);
    // 400g should hit the 500g bracket (300 cents)
    expect(calc.computeShippingCents([makeLine("a", 100, 1, 400)], 100)).toBe(300);
  });

  it("sums weight across multiple lines", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
    ]);
    const lines = [
      makeLine("a", 100, 2, 200), // 400g
      makeLine("b", 100, 1, 300), // 300g → total 700g
    ];
    expect(calc.computeShippingCents(lines, 100)).toBe(500);
  });
});

