describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it("returns 0 for positive subtotal", () => {
    expect(policy.computeDiscountCents(10000)).toBe(0);
  });

  it("returns 0 for zero subtotal", () => {
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  it("rejects negative percent", () => {
    expect(() => new PercentageDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("rejects percent > 100", () => {
    expect(() => new PercentageDiscountPolicy(101)).toThrow(RangeError);
  });

  it("rejects NaN", () => {
    expect(() => new PercentageDiscountPolicy(NaN)).toThrow(RangeError);
  });

  it("rejects Infinity", () => {
    expect(() => new PercentageDiscountPolicy(Infinity)).toThrow(RangeError);
  });

  it("accepts 0%", () => {
    const p = new PercentageDiscountPolicy(0);
    expect(p.computeDiscountCents(10000)).toBe(0);
  });

  it("accepts 100%", () => {
    const p = new PercentageDiscountPolicy(100);
    expect(p.computeDiscountCents(10000)).toBe(10000);
  });

  it("computes 10% of 10000 = 1000", () => {
    const p = new PercentageDiscountPolicy(10);
    expect(p.computeDiscountCents(10000)).toBe(1000);
  });

  it("rounds down to nearest cent", () => {
    const p = new PercentageDiscountPolicy(33);
    // 33% of 100 = 33.0 exactly
    expect(p.computeDiscountCents(100)).toBe(33);
    // 33% of 101 = 33.33 → floor to 33
    expect(p.computeDiscountCents(101)).toBe(33);
  });

  it("returns 0 for zero subtotal", () => {
    const p = new PercentageDiscountPolicy(50);
    expect(p.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const p = new PercentageDiscountPolicy(50);
    expect(p.computeDiscountCents(-100)).toBe(0);
  });

  it("handles very large subtotal", () => {
    const p = new PercentageDiscountPolicy(15);
    expect(p.computeDiscountCents(999999999)).toBe(Math.floor(999999999 * 0.15));
  });
});

describe("FixedAmountDiscountPolicy", () => {
  it("rejects negative amountCents", () => {
    expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("rejects non-integer amountCents", () => {
    expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
  });

  it("accepts 0", () => {
    const p = new FixedAmountDiscountPolicy(0);
    expect(p.computeDiscountCents(5000)).toBe(0);
  });

  it("returns the fixed amount when subtotal exceeds it", () => {
    const p = new FixedAmountDiscountPolicy(500);
    expect(p.computeDiscountCents(10000)).toBe(500);
  });

  it("caps at subtotal when discount exceeds subtotal", () => {
    const p = new FixedAmountDiscountPolicy(5000);
    expect(p.computeDiscountCents(3000)).toBe(3000);
  });

  it("returns 0 for zero subtotal", () => {
    const p = new FixedAmountDiscountPolicy(500);
    expect(p.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const p = new FixedAmountDiscountPolicy(500);
    expect(p.computeDiscountCents(-100)).toBe(0);
  });
});

describe("CompositeDiscountPolicy", () => {
  it("rejects empty policy list", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      "CompositeDiscountPolicy requires at least one policy",
    );
  });

  describe("sum mode", () => {
    it("sums individual discounts against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 10000 = 1000, fixed = 200 → sum = 1200
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });

    it("each policy receives the original subtotal, not the reduced one", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new PercentageDiscountPolicy(50)],
        "sum",
      );
      // Both get 10000: 5000 + 5000 = 10000
      expect(composite.computeDiscountCents(10000)).toBe(10000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(-50)).toBe(0);
    });

    it("clamps negative child returns to 0", () => {
      const negativePolicy = {
        computeDiscountCents: () => -100,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // -100 clamped to 0, fixed = 200 → 200
      expect(composite.computeDiscountCents(10000)).toBe(200);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // First: 10% of 10000 = 1000 → remaining 9000
      // Second: 10% of 9000 = 900 → remaining 8100
      // Total discount = 1900
      expect(composite.computeDiscountCents(10000)).toBe(1900);
    });

    it("order matters in chain mode", () => {
      const composite1 = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500), new PercentageDiscountPolicy(10)],
        "chain",
      );
      const composite2 = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      const subtotal = 10000;
      // composite1: fixed 500, remaining 9500 → 10% of 9500 = 950 → total 1450
      expect(composite1.computeDiscountCents(subtotal)).toBe(1450);
      // composite2: 10% of 10000 = 1000, remaining 9000 → fixed 500 → total 1500
      expect(composite2.computeDiscountCents(subtotal)).toBe(1500);
    });

    it("stops once remaining is exhausted", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(8000), new FixedAmountDiscountPolicy(5000)],
        "chain",
      );
      // First: min(8000, 10000) = 8000, remaining 2000
      // Second: min(5000, 2000) = 2000
      // Total = 10000
      expect(composite.computeDiscountCents(10000)).toBe(10000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child returns to 0 in chain mode", () => {
      const negativePolicy = {
        computeDiscountCents: () => -100,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // negative clamped to 0, then fixed 200
      expect(composite.computeDiscountCents(10000)).toBe(200);
    });
  });

  it("defaults to sum mode", () => {
    const composite = new CompositeDiscountPolicy([
      new FixedAmountDiscountPolicy(100),
      new FixedAmountDiscountPolicy(200),
    ]);
    expect(composite.computeDiscountCents(10000)).toBe(300);
  });
});
