      discountPolicy: { computeDiscountCents: () => 500 },
      shippingCalculator: { computeShippingCents: () => 300 },
      region: "US-NY",
    });
    cart.add(product("a", 5000), 1);
    const result = await cart.checkout({ asyncTaxProvider: asyncProvider });
    // subtotal=5000, discount=500, discounted=4500
    // tax=8% of 4500 = 360
    // shipping=300
    // total=4500+360+300=5160
    expect(result.totals.subtotalCents).toBe(5000);
    expect(result.totals.discountCents).toBe(500);
    expect(result.totals.taxCents).toBe(360);
    expect(result.totals.shippingCents).toBe(300);
    expect(result.totals.totalCents).toBe(5160);
    expect(asyncProvider.getRate).toHaveBeenCalledWith("US-NY");
  });

  it("propagates asyncTaxProvider failure", async () => {
    const asyncProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    await expect(
      cart.checkout({ asyncTaxProvider: asyncProvider }),
    ).rejects.toThrow("tax service down");
  });

  it("propagates priceFetcher failure", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service error")),
    };
    await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
      "price service error",
    );
  });

  it("first denial wins when multiple items fail inventory", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    cart.add(product("b", 2000), 3);
    const checker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: false, reason: "a is out" })
        .mockResolvedValueOnce({ available: false, reason: "b is out" }),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      // Only the first product checked should cause the error
      expect(checker.check).toHaveBeenCalledTimes(1);
    }
  });

  it("generates default reason when none provided", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 5);
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 2,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.message).toContain("insufficient stock");
      expect(ie.message).toContain("a");
    }
  });

  it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
    const cart = new Cart({
      discountPolicy: { computeDiscountCents: () => 100 },
      shippingCalculator: { computeShippingCents: () => 200 },
      region: "FR",
    });
    cart.add(product("a", 1000), 1);

    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(2000),
    };
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };
    const taxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.2),
    };

    const result = await cart.checkout({
      priceFetcher: fetcher,
      inventoryChecker: checker,
      asyncTaxProvider: taxProvider,
    });

    // After price refresh: subtotal=2000, discount=100, discounted=1900
    // tax=20% of 1900 = 380, shipping=200
    // total = 1900 + 380 + 200 = 2480
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.totals.discountCents).toBe(100);
    expect(result.totals.taxCents).toBe(380);
    expect(result.totals.shippingCents).toBe(200);
    expect(result.totals.totalCents).toBe(2480);
    expect(taxProvider.getRate).toHaveBeenCalledWith("FR");
  });
});
"}

