      const composite1 = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500), new PercentageDiscountPolicy(10)],
        "chain",
      );
      const composite2 = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      const subtotal = 10000;
      // composite1: fixed 500, remaining 9500 → 10% of 9500 = 950 → total 1450
      expect(composite1.computeDiscountCents(subtotal)).toBe(1450);
      // composite2: 10% of 10000 = 1000, remaining 9000 → fixed 500 → total 1500
      expect(composite2.computeDiscountCents(subtotal)).toBe(1500);
    });

    it("stops once remaining is exhausted", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(8000), new FixedAmountDiscountPolicy(5000)],
        "chain",
      );
      // First: min(8000, 10000) = 8000, remaining 2000
      // Second: min(5000, 2000) = 2000
      // Total = 10000
      expect(composite.computeDiscountCents(10000)).toBe(10000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child returns to 0 in chain mode", () => {
      const negativePolicy = {
        computeDiscountCents: () => -100,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // negative clamped to 0, then fixed 200
      expect(composite.computeDiscountCents(10000)).toBe(200);
    });
  });

  it("defaults to sum mode", () => {
    const composite = new CompositeDiscountPolicy([
      new FixedAmountDiscountPolicy(100),
      new FixedAmountDiscountPolicy(200),
    ]);
    expect(composite.computeDiscountCents(10000)).toBe(300);
  });
});

