+    const cart = new Cart();
+    const t = cart.totals();
+    expect(t.subtotalCents).toBe(0);
+    expect(t.discountCents).toBe(0);
+    expect(t.taxCents).toBe(0);
+    expect(t.shippingCents).toBe(0);
+    expect(t.totalCents).toBe(0);
+  });
+
+  it("computes subtotal as sum of unitPriceCents * quantity", () => {
+    const cart = new Cart();
+    cart.add(product("a", 1000), 2); // 2000
+    cart.add(product("b", 500), 3); // 1500
+    expect(cart.totals().subtotalCents).toBe(3500);
+  });
+
+  it("uses injected discount policy", () => {
+    const mockDiscount: DiscountPolicy = {
+      computeDiscountCents: vi.fn().mockReturnValue(300),
+    };
+    const cart = new Cart({ discountPolicy: mockDiscount });
+    cart.add(product("a", 1000), 1);
+    const t = cart.totals();
+    expect(t.discountCents).toBe(300);
+    expect(mockDiscount.computeDiscountCents).toHaveBeenCalledWith(1000);
+  });
+
+  it("clamps discount to [0, subtotal]", () => {
+    const overDiscount: DiscountPolicy = {
+      computeDiscountCents: vi.fn().mockReturnValue(5000),
+    };
+    const cart = new Cart({ discountPolicy: overDiscount });
+    cart.add(product("a", 1000), 1);
+    const t = cart.totals();
+    expect(t.discountCents).toBe(1000); // clamped to subtotal
+  });
+
+  it("clamps negative discount to 0", () => {
+    const negDiscount: DiscountPolicy = {
+      computeDiscountCents: vi.fn().mockReturnValue(-500),
+    };
+    const cart = new Cart({ discountPolicy: negDiscount });
+    cart.add(product("a", 1000), 1);
+    expect(cart.totals().discountCents).toBe(0);
+  });
+
+  it("tax is computed on discounted subtotal", () => {
+    const mockTax: TaxCalculator = {
+      computeTaxCents: vi.fn().mockReturnValue(80),
+    };
+    const mockDiscount: DiscountPolicy = {
+      computeDiscountCents: vi.fn().mockReturnValue(200),
+    };
+    const cart = new Cart({
+      discountPolicy: mockDiscount,
+      taxCalculator: mockTax,
+      region: "US-CA",
+    });
+    cart.add(product("a", 1000), 1);
+    cart.totals();
+    // discounted subtotal = 1000 - 200 = 800
+    expect(mockTax.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
+  });
+
+  it("shipping receives lines and discounted subtotal", () => {
+    const mockShipping: ShippingCalculator = {
+      computeShippingCents: vi.fn().mockReturnValue(599),
+    };
+    const mockDiscount: DiscountPolicy = {
+      computeDiscountCents: vi.fn().mockReturnValue(100),
+    };
+    const cart = new Cart({
+      discountPolicy: mockDiscount,
+      shippingCalculator: mockShipping,
+    });
+    cart.add(product("a", 500), 2); // subtotal 1000
+    cart.totals();
+    const callArgs = (mockShipping.computeShippingCents as ReturnType<typeof vi.fn>).mock.calls[0]!;
+    expect(callArgs[1]).toBe(900); // discounted subtotal
+    expect(callArgs[0]).toHaveLength(1); // one line
+  });
+
+  it("totalCents = discountedSubtotal + tax + shipping", () => {
+    const cart = new Cart({
+      discountPolicy: { computeDiscountCents: () => 200 },
+      taxCalculator: { computeTaxCents: () => 80 },
+      shippingCalculator: { computeShippingCents: () => 500 },
+    });
+    cart.add(product("a", 1000), 1);
+    const t = cart.totals();
+    // subtotal=1000, discount=200, discounted=800, tax=80, ship=500
+    expect(t.totalCents).toBe(800 + 80 + 500);
+  });
+
+  it("clamps negative tax to 0", () => {
+    const cart = new Cart({
+      taxCalculator: { computeTaxCents: () => -50 },
+    });
+    cart.add(product("a", 1000), 1);
+    expect(cart.totals().taxCents).toBe(0);
+  });
+
+  it("clamps negative shipping to 0", () => {
+    const cart = new Cart({
+      shippingCalculator: { computeShippingCents: () => -100 },
+    });
+    cart.add(product("a", 1000), 1);
+    expect(cart.totals().shippingCents).toBe(0);
+  });
+
+  it("defaults to NoDiscount, NoTax, FreeShipping, US region", () => {
+    const cart = new Cart();
+    cart.add(product("a", 1000), 2);
+    const t = cart.totals();
+    expect(t.subtotalCents).toBe(2000);
+    expect(t.discountCents).toBe(0);
+    expect(t.taxCents).toBe(0);
+    expect(t.shippingCents).toBe(0);
+    expect(t.totalCents).toBe(2000);
+  });
+});
+
+describe("Cart.checkout()", () => {
+  it("returns totals and lines without collaborators", async () => {
+    const cart = new Cart();
+    cart.add(product("a", 1000), 2);
+    const result = await cart.checkout();
+    expect(result.totals.subtotalCents).toBe(2000);
+    expect(result.lines).toHaveLength(1);
+  });
+
+  it("refreshes prices via priceFetcher", async () => {
+    const cart = new Cart();
+    cart.add(product("a", 1000), 1);
+    const fetcher: PriceFetcher = {
+      fetchPriceCents: vi.fn().mockResolvedValue(1500),
+    };
+    const result = await cart.checkout({ priceFetcher: fetcher });
+    expect(result.totals.subtotalCents).toBe(1500);
+    expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
+  });
+
+  it("throws InventoryError when item is unavailable", async () => {
+    const cart = new Cart();
+    cart.add(product("a", 1000), 5);
+    const checker: InventoryChecker = {
+      check: vi.fn().mockResolvedValue({ available: false, availableQuantity: 0, reason: "sold out" }),
+    };
+    try {
+      await cart.checkout({ inventoryChecker: checker });
+      expect.unreachable("should have thrown");
+    } catch (err) {
+      expect(err).toBeInstanceOf(InventoryError);
+      const ie = err as InventoryError;
+      expect(ie.productId).toBe("a");
+      expect(ie.requested).toBe(5);
+      expect(ie.available).toBe(0);
+      expect(ie.message).toBe("sold out");
+    }
+  });
+
+  it("throws InventoryError on partial-stock denial (availableQuantity < requested)", async () => {
+    const cart = new Cart();
+    cart.add(product("a", 1000), 5);
+    const checker: InventoryChecker = {
+      check: vi.fn().mockResolvedValue({
+        available: true,
+        availableQuantity: 3,
+      }),
+    };
+    try {
+      await cart.checkout({ inventoryChecker: checker });
+      expect.unreachable("should have thrown");
+    } catch (err) {
+      expect(err).toBeInstanceOf(InventoryError);
+      const ie = err as InventoryError;
+      expect(ie.productId).toBe("a");
+      expect(ie.requested).toBe(5);
+      expect(ie.available).toBe(3);
+    }
+  });
+
+  it("passes when inventoryChecker says available with sufficient quantity", async () => {
+    const cart = new Cart();
+    cart.add(product("a", 1000), 2);
+    const checker: InventoryChecker = {
+      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
+    };
+    const result = await cart.checkout({ inventoryChecker: checker });
+    expect(result.totals.subtotalCents).toBe(2000);
+  });
+
+  it("passes when inventoryChecker says available without specifying availableQuantity", async () => {
+    const cart = new Cart();
+    cart.add(product("a", 1000), 2);
+    const checker: InventoryChecker = {
+      check: vi.fn().mockResolvedValue({ available: true }),
+    };
+    const result = await cart.checkout({ inventoryChecker: checker });
+    expect(result.totals.subtotalCents).toBe(2000);
+  });
+
+  it("uses asyncTaxProvider for tax computation", async () => {
+    const asyncProvider: AsyncTaxRateProvider = {
+      getRate: vi.fn().mockResolvedValue(0.1),
+    };
+    const cart = new Cart({
+      discountPolicy: { computeDiscountCents: () => 0 },
+    });
+    cart.add(product("a", 10000), 1);
+    const result = await cart.checkout({ asyncTaxProvider: asyncProvider });
+    // 10% of 10000 = 1000
+    expect(result.totals.taxCents).toBe(1000);
+    expect(asyncProvider.getRate).toHaveBeenCalledWith("US");
+  });
+
+  it("asyncTaxProvider with discount and shipping", async () => {
+    const asyncProvider: AsyncTaxRateProvider = {
+      getRate: vi.fn().mockResolvedValue(0.08),
+    };
+    const cart = new Cart({
+      discountPolicy: { computeDiscountCents: () => 500 },
+      shippingCalculator: { computeShippingCents: () => 300 },
+      region: "US-NY",
+    });
+    cart.add(product("a", 5000), 1);
+    const result = await cart.checkout({ asyncTaxProvider: asyncProvider });
+    // subtotal=5000, discount=500, discounted=4500
+    // tax=8% of 4500 = 360
+    // shipping=300
+    // total=4500+360+300=5160
+    expect(result.totals.subtotalCents).toBe(5000);
+    expect(result.totals.discountCents).toBe(500);
+    expect(result.totals.taxCents).toBe(360);
+    expect(result.totals.shippingCents).toBe(300);
+    expect(result.totals.totalCents).toBe(5160);
+    expect(asyncProvider.getRate).toHaveBeenCalledWith("US-NY");
+  });
+
+  it("propagates asyncTaxProvider failure", async () => {
+    const asyncProvider: AsyncTaxRateProvider = {
+      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
+    };
+    const cart = new Cart();
+    cart.add(product("a", 1000), 1);
+    await expect(
+      cart.checkout({ asyncTaxProvider: asyncProvider }),
+    ).rejects.toThrow("tax service down");
+  });
+
+  it("propagates priceFetcher failure", async () => {
+    const cart = new Cart();
+    cart.add(product("a", 1000), 1);
+    const fetcher: PriceFetcher = {
+      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service error")),
+    };
+    await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
+      "price service error",
+    );
+  });
+
+  it("first denial wins when multiple items fail inventory", async () => {
+    const cart = new Cart();
+    cart.add(product("a", 1000), 2);
+    cart.add(product("b", 2000), 3);
+    const checker: InventoryChecker = {
+      check: vi.fn()
+        .mockResolvedValueOnce({ available: false, reason: "a is out" })
+        .mockResolvedValueOnce({ available: false, reason: "b is out" }),
+    };
+    try {
+      await cart.checkout({ inventoryChecker: checker });
+      expect.unreachable("should have thrown");
+    } catch (err) {
+      expect(err).toBeInstanceOf(InventoryError);
+      // Only the first product checked should cause the error
+      expect(checker.check).toHaveBeenCalledTimes(1);
+    }
+  });
+
+  it("generates default reason when none provided", async () => {
+    const cart = new Cart();
+    cart.add(product("a", 1000), 5);
+    const checker: InventoryChecker = {
+      check: vi.fn().mockResolvedValue({
+        available: false,
+        availableQuantity: 2,
+      }),
+    };
+    try {
+      await cart.checkout({ inventoryChecker: checker });
+      expect.unreachable("should have thrown");
+    } catch (err) {
+      expect(err).toBeInstanceOf(InventoryError);
+      const ie = err as InventoryError;
+      expect(ie.message).toContain("insufficient stock");
+      expect(ie.message).toContain("a");
+    }
+  });
+
+  it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
+    const cart = new Cart({
+      discountPolicy: { computeDiscountCents: () => 100 },
+      shippingCalculator: { computeShippingCents: () => 200 },
+      region: "FR",
+    });
+    cart.add(product("a", 1000), 1);
+
+    const fetcher: PriceFetcher = {
+      fetchPriceCents: vi.fn().mockResolvedValue(2000),
+    };
+    const checker: InventoryChecker = {
+      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
+    };
+    const taxProvider: AsyncTaxRateProvider = {
+      getRate: vi.fn().mockResolvedValue(0.2),
+    };
+
+    const result = await cart.checkout({
+      priceFetcher: fetcher,
+      inventoryChecker: checker,
+      asyncTaxProvider: taxProvider,
+    });
+
+    // After price refresh: subtotal=2000, discount=100, discounted=1900
+    // tax=20% of 1900 = 380, shipping=200
+    // total = 1900 + 380 + 200 = 2480
+    expect(result.totals.subtotalCents).toBe(2000);
+    expect(result.totals.discountCents).toBe(100);
+    expect(result.totals.taxCents).toBe(380);
+    expect(result.totals.shippingCents).toBe(200);
+    expect(result.totals.totalCents).toBe(2480);
+    expect(taxProvider.getRate).toHaveBeenCalledWith("FR");
+  });
+});
